--
-- Name: add_recipe_with_ingredients(character varying, character varying, text, integer, character varying, integer, integer[], numeric[], character varying[]); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.add_recipe_with_ingredients(IN p_title character varying, IN p_cuisine character varying, IN p_instructions text, IN p_prep integer, IN p_difficulty character varying, IN p_created_by integer, IN p_ingredient_ids integer[], IN p_quantities numeric[], IN p_units character varying[])
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recipe_id INT;
  i INT;
BEGIN
  VALUES (p_title, p_cuisine, p_instructions, p_prep, p_difficulty, p_created_by)
  RETURNING recipe_id INTO v_recipe_id;

  FOR i IN 1 .. array_length(p_ingredient_ids, 1) LOOP
    VALUES (v_recipe_id, p_ingredient_ids[i], p_quantities[i], p_units[i]);
  END LOOP;

  COMMIT;
END;
$$;


ALTER PROCEDURE public.add_recipe_with_ingredients(IN p_title character varying, IN p_cuisine character varying, IN p_instructions text, IN p_prep integer, IN p_difficulty character varying, IN p_created_by integer, IN p_ingredient_ids integer[], IN p_quantities numeric[], IN p_units character varying[]) OWNER TO postgres;

--
-- Name: fn_update_avg_rating(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_avg_rating() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE recipes
  SET avg_rating = COALESCE((
    SELECT ROUND(AVG(stars)::numeric, 2) FROM ratings
    WHERE recipe_id = COALESCE(NEW.recipe_id, OLD.recipe_id)
  ), 0)
  WHERE recipe_id = COALESCE(NEW.recipe_id, OLD.recipe_id);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_update_avg_rating() OWNER TO postgres;

--
-- Name: get_pantry_match(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pantry_match(p_user_id integer) RETURNS TABLE(recipe_id integer, title character varying, total_needed bigint, matched bigint, match_pct numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT r.recipe_id, r.title,
         COUNT(ri.ingredient_id) AS total_needed,
         COUNT(up.ingredient_id) AS matched,
         ROUND(100.0 * COUNT(up.ingredient_id) / COUNT(ri.ingredient_id), 1) AS match_pct
  FROM recipes r
  JOIN recipe_ingredients ri ON ri.recipe_id = r.recipe_id
  LEFT JOIN user_pantry up ON up.ingredient_id = ri.ingredient_id AND up.user_id = p_user_id
  GROUP BY r.recipe_id, r.title
  HAVING COUNT(up.ingredient_id) > 0
  ORDER BY match_pct DESC, matched DESC
  LIMIT 20;
END;
$$;


ALTER FUNCTION public.get_pantry_match(p_user_id integer) OWNER TO postgres;

